// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        uint256 INIT = 100 ether;
        vm.assume(amount > 0 && amount <= INIT);

        vm.deal(address(c), INIT);
        uint256 balBefore = address(c).balance;

        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }

        uint256 balAfter = address(c).balance;

        assertTrue(!ok || balAfter == balBefore - amount);
    }
}
